B=[
('طَنْجَةُ','Tanca',[
('فِي سَنَةِ إِحْدَى وَتِسْعِينَ لِلْهِجْرَةِ كَانَ مُوسَى بْنُ نُصَيْرٍ وَالِيًا عَلَى إِفْرِيقِيَةَ.','Hicrî 91 yılında Mûsâ b. Nusayr İfrîkıye valisiydi.'),
('وَكَانَ مَوْلَاهُ طَارِقُ بْنُ زِيَادٍ أَمِيرًا عَلَى طَنْجَةَ، وَهُوَ شَابٌّ شُجَاعٌ مِنَ الْبَرْبَرِ.','Mevlâsı Târık b. Ziyâd, Berberîlerden cesur bir genç olarak Tanca emiriydi.'),
('وَكَانَ وَرَاءَ الْبَحْرِ بِلَادٌ وَاسِعَةٌ يَحْكُمُهَا الْقُوطُ، وَمَلِكُهُمْ لُذْرِيقُ.','Denizin ötesinde Gotların hükmettiği geniş bir ülke vardı; kralları Rodrigo idi.'),
('وَكَانَ النَّاسُ هُنَاكَ يَشْكُونَ مِنْ ظُلْمِ لُذْرِيقَ وَكَثْرَةِ الضَّرَائِبِ.','Oradaki insanlar Rodrigo’nun zulmünden ve vergilerin çokluğundan şikâyet ediyordu.'),
('فَجَاءَ إِلَى طَارِقٍ رَجُلٌ مِنْ سَبْتَةَ يُقَالُ لَهُ يُولْيَانُ، وَكَانَ عَدُوًّا لِلُذْرِيقَ.','Târık’a Septeli Julian denen, Rodrigo’nun düşmanı bir adam geldi.'),
('فَقَالَ: «إِنْ عَبَرْتُمُ الْبَحْرَ، فَأَنَا أُعِينُكُمْ بِالسُّفُنِ وَالْأَدِلَّاءِ.»','Dedi ki: “Denizi geçerseniz, size gemilerle ve kılavuzlarla yardım ederim.”')]),
('عُبُورُ الْبَحْرِ','Denizin geçilişi',[
('فَكَتَبَ مُوسَى إِلَى الْخَلِيفَةِ الْوَلِيدِ بْنِ عَبْدِ الْمَلِكِ يَسْتَأْذِنُهُ.','Mûsâ halife Velîd b. Abdülmelik’e izin istemek için yazdı.'),
('فَأَذِنَ لَهُ، وَقَالَ: «لَا تُغَرِّرْ بِالْمُسْلِمِينَ فِي بَحْرٍ شَدِيدِ الْأَهْوَالِ.»','Halife izin verdi ve dedi ki: “Müslümanları dehşetli bir denizde tehlikeye atma.”'),
('فَعَبَرَ طَارِقٌ فِي سَبْعَةِ آلَافِ رَجُلٍ، وَنَزَلَ عِنْدَ جَبَلٍ عَلَى السَّاحِلِ.','Târık yedi bin adamla denizi geçti ve kıyıdaki bir dağın yanına indi.'),
('فَسُمِّيَ ذَلِكَ الْجَبَلُ بِاسْمِهِ إِلَى الْيَوْمِ: جَبَلَ طَارِقٍ.','O dağ bugüne kadar onun adıyla anılır: Cebelitârık.'),
('وَيُرْوَى أَنَّهُ قَامَ فِي جُنُودِهِ خَطِيبًا وَقَالَ: «أَيْنَ الْمَفَرُّ؟ الْبَحْرُ مِنْ وَرَائِكُمْ وَالْعَدُوُّ أَمَامَكُمْ.»','Rivayete göre askerlerinin önünde hutbe verip dedi ki: “Kaçış nereye? Deniz arkanızda, düşman önünüzde.”'),
('«وَلَيْسَ لَكُمْ وَاللَّهِ إِلَّا الصِّدْقُ وَالصَّبْرُ.»','“Vallahi sizin için sadakat ve sabırdan başka bir şey yok.”')]),
('وَادِي لَكَّةَ','Guadalete vadisi',[
('فَلَمَّا سَمِعَ لُذْرِيقُ بِذَلِكَ جَمَعَ جَيْشًا عَظِيمًا، يُقَالُ إِنَّهُ مِائَةُ أَلْفٍ.','Rodrigo bunu duyunca yüz bin olduğu söylenen büyük bir ordu topladı.'),
('فَأَرْسَلَ مُوسَى إِلَى طَارِقٍ خَمْسَةَ آلَافِ رَجُلٍ مَدَدًا.','Mûsâ Târık’a yardım olarak beş bin adam gönderdi.'),
('وَالْتَقَى الْجَيْشَانِ عِنْدَ وَادِي لَكَّةَ، وَدَامَتِ الْمَعْرَكَةُ ثَمَانِيَةَ أَيَّامٍ.','İki ordu Guadalete vadisinde karşılaştı ve savaş sekiz gün sürdü.'),
('وَكَانَ كَثِيرٌ مِنْ جُنُودِ لُذْرِيقَ يَكْرَهُونَهُ، فَتَرَكُوهُ فِي وَسَطِ الْقِتَالِ.','Rodrigo’nun askerlerinin çoğu ondan nefret ediyordu ve onu savaşın ortasında bıraktılar.'),
('فَانْهَزَمَ الْقُوطُ، وَضَاعَ لُذْرِيقُ فَلَمْ يُعْرَفْ لَهُ خَبَرٌ.','Gotlar yenildi; Rodrigo kayboldu ve ondan bir daha haber alınamadı.'),
('فَفُتِحَتْ أَبْوَابُ الْأَنْدَلُسِ أَمَامَ الْمُسْلِمِينَ.','Endülüs’ün kapıları Müslümanların önüne açıldı.')]),
('طُلَيْطِلَةُ','Toledo',[
('سَارَ طَارِقٌ إِلَى طُلَيْطِلَةَ، عَاصِمَةِ الْقُوطِ، فَوَجَدَهَا خَالِيَةً.','Târık Gotların başkenti Toledo’ya yürüdü ve onu boş buldu.'),
('وَكَانَ أَهْلُ الْمُدُنِ يَفْتَحُونَ الْأَبْوَابَ، لِأَنَّ الْمُسْلِمِينَ كَانُوا يُعْطُونَهُمُ الْأَمَانَ عَلَى دِينِهِمْ وَأَمْوَالِهِمْ.','Şehirlerin halkı kapıları açıyordu; çünkü Müslümanlar onlara dinleri ve malları üzerine aman veriyordu.'),
('وَكَانَ الْيَهُودُ قَدْ ظُلِمُوا كَثِيرًا مِنَ الْقُوطِ، فَفَرِحُوا بِالْفَاتِحِينَ.','Yahudiler Gotlardan çok zulüm görmüşlerdi; fatihlere sevindiler.'),
('ثُمَّ عَبَرَ مُوسَى بْنُ نُصَيْرٍ بِجَيْشٍ آخَرَ، وَفَتَحَ إِشْبِيلِيَةَ وَمَارِدَةَ.','Sonra Mûsâ b. Nusayr başka bir orduyla geçti ve Sevilla’yı ve Mérida’yı fethetti.'),
('وَالْتَقَى بِطَارِقٍ، فَعَاتَبَهُ لِأَنَّهُ تَقَدَّمَ بِغَيْرِ إِذْنِهِ، ثُمَّ رَضِيَ عَنْهُ.','Târık’la buluştu; izinsiz ilerlediği için onu azarladı, sonra ondan razı oldu.'),
('وَفُتِحَتِ الْبِلَادُ حَتَّى جِبَالِ الشَّمَالِ فِي سَنَوَاتٍ قَلِيلَةٍ.','Birkaç yıl içinde ülke kuzeydeki dağlara kadar fethedildi.')]),
('الْعَوْدَةُ إِلَى دِمَشْقَ','Dımaşk’a dönüş',[
('ثُمَّ أَمَرَ الْخَلِيفَةُ مُوسَى وَطَارِقًا أَنْ يَرْجِعَا إِلَى دِمَشْقَ.','Sonra halife Mûsâ ile Târık’ın Dımaşk’a dönmelerini emretti.'),
('فَرَجَعَا، وَمَعَهُمَا الْغَنَائِمُ وَالْأَسْرَى.','İkisi ganimetler ve esirlerle döndüler.'),
('وَلَكِنَّ الْخَلِيفَةَ الْوَلِيدَ مَاتَ، وَجَاءَ أَخُوهُ سُلَيْمَانُ، فَلَمْ يُكْرِمْهُمَا كَمَا يَنْبَغِي.','Ama halife Velîd öldü ve kardeşi Süleyman geldi; onlara layıkıyla ikram etmedi.'),
('فَعَاشَ الْفَاتِحَانِ بَقِيَّةَ أَيَّامِهِمَا بَعِيدَيْنِ عَنِ الْمَجْدِ الَّذِي صَنَعَاهُ.','İki fatih ömürlerinin geri kalanını yarattıkları şandan uzak geçirdiler.'),
('أَمَّا الْأَنْدَلُسُ فَبَقِيَتْ فِي أَيْدِي الْمُسْلِمِينَ نَحْوَ ثَمَانِمِائَةِ سَنَةٍ.','Endülüs ise yaklaşık sekiz yüz yıl Müslümanların elinde kaldı.'),
('وَصَارَتْ قُرْطُبَةُ وَإِشْبِيلِيَةُ وَغَرْنَاطَةُ مَنَارَاتٍ لِلْعِلْمِ فِي الدُّنْيَا كُلِّهَا.','Kurtuba, Sevilla ve Gırnata bütün dünyada ilmin fenerleri oldu.')]),
]
